<script setup lang="ts">
import { computed, reactive, watch } from 'vue'
import type { RunInput, WorkbenchRun } from '../../types/workbench'
import { isolatedDemo } from '../../utils/runtime'
const props = defineProps<{ disabled: boolean; selected?: WorkbenchRun; canOperate: boolean; suggestedQuestion?: string; initialAnalysisId?: string }>()
const emit = defineEmits<{ create: [value: RunInput] }>()
const form = reactive<RunInput>({ question: '请说明这次巡检应如何处理，列出已知事实、缺失证据及下一步建议，不生成方案或执行。', mode: 'demo', external_allowed: false, source_kind: 'none', source_id: '', compare_id: '', parent_id: '' })
const valid = computed(() => !!form.question.trim() && (form.source_kind === 'none' || !!form.source_id.trim()) && (form.mode === 'demo' || (props.canOperate && form.external_allowed)))
watch(() => props.selected?.id, () => { form.parent_id = '' })
watch(() => props.suggestedQuestion, q => { if (q) { follow(); form.question = q } })
watch(() => props.initialAnalysisId, id => { if (id) { form.source_kind='analysis';form.source_id=id;form.mode='live';form.external_allowed=false;form.question='请解释所选分析的预测框、标签、置信度与局限，指出还需要哪些人工复核信息。' } }, {immediate:true})
function follow() { if (props.selected?.checkpoint.answer) { form.parent_id = props.selected.id; form.mode = props.selected.input.mode === 'demo' ? 'demo' : 'live'; form.source_kind = (props.selected.input.source_kind as RunInput['source_kind']) || 'none'; form.source_id = props.selected.input.source_id || ''; form.compare_id = props.selected.input.compare_id || ''; form.question = '请针对刚才的证据继续解释，还缺什么信息？'; form.external_allowed = false } }
</script>
<template><section class="composer"><h2>新建分析运行</h2><p>独立样例不调用模型或真实业务。真实分析会把问题、所选证据及检索片段发送给外部模型；分析阶段没有生成方案或执行工具。</p><label>运行方式<select v-model="form.mode" :disabled="disabled"><option value="demo">独立合成样例回放</option><option value="live" :disabled="!canOperate || isolatedDemo">真实Agent分析（需授权）</option></select></label><label>证据类型<select v-model="form.source_kind" :disabled="disabled"><option value="none">不指定，由工具查询明确范围</option><option value="task">任务编号</option><option value="event">事件编号</option><option value="analysis">图像分析编号</option></select></label><label v-if="form.source_kind !== 'none'">所选记录编号<input v-model="form.source_id" maxlength="40" :disabled="disabled"></label><label v-if="form.source_kind === 'analysis'">对比分析编号（可选）<input v-model="form.compare_id" maxlength="40" :disabled="disabled"></label><label>问题<textarea v-model="form.question" rows="4" maxlength="2000" :disabled="disabled" /></label><p v-if="form.source_kind === 'analysis'">回答基于YOLO预测框与版本，不是视觉大模型直接看图；不推断拍摄地点。可到检测历史选取编号。</p><label v-if="form.mode === 'live'"><input v-model="form.external_allowed" type="checkbox" :disabled="disabled">我确认可将本次问题和所选业务/知识证据发送给已配置的外部模型</label><p v-if="form.parent_id">继续运行 {{ form.parent_id }} 的对话；本轮会重新查证所选记录。</p><button :disabled="disabled || !valid" @click="emit('create', { ...form })">开始分析</button><button :disabled="disabled || !selected?.checkpoint.answer" @click="follow">围绕所选证据继续追问</button></section></template>
<style scoped>.composer{padding:18px;background:#102537;border:1px solid #31546b}.composer label{display:block;margin:10px 0}.composer input:not([type=checkbox]),.composer select,.composer textarea{display:block;width:100%;max-width:650px;box-sizing:border-box;margin-top:5px;padding:8px;background:#081c2a;color:#e0eff7;border:1px solid #36536b}.composer p{color:#9ebfd2;font-size:13px;line-height:1.8}.composer button{margin:8px 10px 0 0}</style>
